import { supabase } from '../supabase';
import { getSystemInfo } from './getSystemInfo';

/**
 * Register web browser as a device
 * Used when running on web or desktop without FCM
 */
export const registerWebDevice = async (userId) => {
  try {
    if (!userId) {
      console.warn('No user ID for web device registration');
      return null;
    }

    const systemInfo = await getSystemInfo();
    const viewportWidth = typeof window !== 'undefined' && window.innerWidth ? window.innerWidth : 'unknown';
    const viewportHeight = typeof window !== 'undefined' && window.innerHeight ? window.innerHeight : 'unknown';
    
    // Use stable browser characteristics as the device token so repeated calls update the same row
    const token = `web_${navigator.userAgent.slice(0, 50)}_${viewportWidth}x${viewportHeight}`;

    console.log('[Web Device] Registering with token:', token);

    const { error } = await supabase.rpc('upsert_device_token', {
      _user_id: userId,
      _token: token,
      _platform: systemInfo.platform || 'web',
      _metadata: systemInfo
    });

    if (error) {
      console.error('[Web Device] Registration failed:', error);
      return null;
    }

    try {
      localStorage.setItem('device_token', token);
    } catch (storageErr) {
      console.warn('[Web Device] Could not persist device token:', storageErr);
    }

    console.log('[Web Device] ✅ Registered successfully');
    return token;
  } catch (err) {
    console.error('[Web Device] Error registering device:', err);
    return null;
  }
};

/**
 * Update web device metadata periodically
 * Useful for tracking last activity, connection changes, etc.
 */
export const updateWebDeviceMetadata = async (userId, token) => {
  try {
    if (!userId || !token) return;

    const systemInfo = await getSystemInfo();

    const { error } = await supabase
      .from('device_tokens')
      .update({ 
        metadata: systemInfo,
        updated_at: new Date().toISOString()
      })
      .eq('user_id', userId)
      .eq('token', token);

    if (error) {
      console.warn('[Web Device] Metadata update failed:', error);
      return false;
    }

    return true;
  } catch (err) {
    console.error('[Web Device] Error updating metadata:', err);
    return false;
  }
};
