/**
 * Utility to gather detailed system information for device registration
 */
export const getSystemInfo = async () => {
  try {
    const info = {
      platform: 'web', // Default to web
      user_agent: navigator.userAgent || '',
      screen_resolution: `${window.screen.width}x${window.screen.height}`,
      language: navigator.language || 'unknown',
      timestamp: new Date().toISOString()
    };

    // Detect OS and browser from user agent
    const ua = navigator.userAgent.toLowerCase();
    
    // Detect OS
    if (ua.includes('win')) {
      info.platform = 'windows';
      info.os_version = 'Windows';
    } else if (ua.includes('mac')) {
      info.platform = 'macos';
      info.os_version = 'macOS';
    } else if (ua.includes('linux')) {
      info.platform = 'linux';
      info.os_version = 'Linux';
    } else if (ua.includes('android')) {
      info.platform = 'android';
      info.os_version = 'Android';
    } else if (ua.includes('iphone') || ua.includes('ipad')) {
      info.platform = 'ios';
      info.os_version = 'iOS';
    }

    // Detect browser
    if (ua.includes('edge')) {
      info.browser_version = 'Microsoft Edge';
    } else if (ua.includes('chrome')) {
      info.browser_version = 'Chrome';
    } else if (ua.includes('firefox')) {
      info.browser_version = 'Firefox';
    } else if (ua.includes('safari')) {
      info.browser_version = 'Safari';
    }

    // Get device memory if available
    if (navigator.deviceMemory) {
      info.device_memory = `${navigator.deviceMemory}GB`;
    }

    // Get cores if available
    if (navigator.hardwareConcurrency) {
      info.cpu_cores = navigator.hardwareConcurrency;
    }

    // Get connection type if available
    if (navigator.connection) {
      info.connection_type = navigator.connection.effectiveType || 'unknown';
    }

    // Try to get device name from Capacitor if available
    if (window.Capacitor?.Plugins?.Device) {
      try {
        const deviceInfo = await window.Capacitor.Plugins.Device.getInfo();
        info.device_model = deviceInfo.model || '';
        info.app_version = deviceInfo.appVersion || '';
        if (deviceInfo.osVersion) {
          info.os_version = `${deviceInfo.osVersion}`;
        }
      } catch (err) {
        console.warn('Failed to get Capacitor device info:', err);
      }
    }

    return info;
  } catch (err) {
    console.error('Error gathering system info:', err);
    return {
      platform: 'web',
      user_agent: navigator.userAgent || '',
      screen_resolution: `${window.screen.width}x${window.screen.height}`,
      timestamp: new Date().toISOString()
    };
  }
};
